CREATE TYPE public.app_role AS ENUM ('admin','manager','cashier','staff');
CREATE TABLE public.admin_audit_logs (id uuid DEFAULT gen_random_uuid() NOT NULL, actor_id uuid DEFAULT auth.uid() NOT NULL, actor_label text, action text NOT NULL, resource_type text NOT NULL, resource_id text, previous_value text, new_value text, status text DEFAULT 'success'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.business_characteristics (business_id uuid NOT NULL, legal_form text, business_type text, sector text, employee_count integer, tax_registrations text[] DEFAULT '{}'::text[] NOT NULL, does_import boolean DEFAULT false NOT NULL, does_export boolean DEFAULT false NOT NULL, flags jsonb DEFAULT '{}'::jsonb NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.business_settings (setting_key text NOT NULL, user_id uuid DEFAULT auth.uid() NOT NULL, setting_value text DEFAULT ''::text NOT NULL, description text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.business_subscription (business_id uuid NOT NULL, plan text DEFAULT 'full'::text NOT NULL, status text DEFAULT 'active'::text NOT NULL, expires_at timestamp with time zone, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.campaign_results (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), campaign_id uuid NOT NULL, impressions integer DEFAULT 0 NOT NULL, reach integer DEFAULT 0 NOT NULL, engagement integer DEFAULT 0 NOT NULL, clicks integer DEFAULT 0 NOT NULL, leads integer DEFAULT 0 NOT NULL, customers_acquired integer DEFAULT 0 NOT NULL, revenue numeric DEFAULT 0 NOT NULL, extra_cost numeric DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.campaign_share_plan (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), campaign_id uuid, channel_id uuid, channel text, content text NOT NULL, audience_id uuid, publish_date date, publish_time time without time zone, owner text, status text DEFAULT 'planned'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT campaign_share_plan_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'scheduled'::text, 'published'::text, 'cancelled'::text]))));
CREATE TABLE public.capital_assets (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, category text, purchase_date date DEFAULT CURRENT_DATE NOT NULL, purchase_value numeric DEFAULT 0 NOT NULL, current_value numeric DEFAULT 0 NOT NULL, depreciation numeric DEFAULT 0 NOT NULL, useful_life integer DEFAULT 5 NOT NULL, status text DEFAULT 'Active'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.compliance_evidence (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), obligation_id uuid NOT NULL, document_id uuid NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.compliance_licences (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), obligation_id uuid, name text NOT NULL, licence_type text, authority text, reference text, issue_date date, expiry_date date, renewal_required boolean DEFAULT false NOT NULL, renewal_frequency text, fee_amount numeric, payment_status text, status text DEFAULT 'Active'::text NOT NULL, document_id uuid, notes text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.compliance_obligations (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), rule_id uuid, name text NOT NULL, category text NOT NULL, authority text, description text, applicability text DEFAULT 'requires_review'::text NOT NULL, registration_state text, frequency text, period text, due_date date, expiry_date date, filing_required boolean DEFAULT false NOT NULL, filing_status text, payment_required boolean DEFAULT false NOT NULL, amount_due numeric, payment_status text, evidence_required boolean DEFAULT false NOT NULL, document_id uuid, reminder_on boolean DEFAULT true NOT NULL, notes text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.compliance_rules (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, category text NOT NULL, authority text, description text, basis text DEFAULT 'profile'::text NOT NULL, conditions jsonb DEFAULT '[]'::jsonb NOT NULL, frequency text DEFAULT 'Periodic'::text NOT NULL, requires_filing boolean DEFAULT false NOT NULL, requires_payment boolean DEFAULT false NOT NULL, requires_renewal boolean DEFAULT false NOT NULL, requires_evidence boolean DEFAULT false NOT NULL, due_rule jsonb, configured boolean DEFAULT false NOT NULL, notes text, active boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.customer_channels (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, type text DEFAULT 'digital'::text NOT NULL, notes text, active boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.customer_interactions (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid() NOT NULL, customer_id uuid NOT NULL, occurred_at timestamp with time zone DEFAULT now() NOT NULL, interaction_type text DEFAULT 'call'::text NOT NULL, channel text, outcome text, notes text, next_follow_up date, staff_name text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.customers (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, phone text, location text, address text, customer_type text DEFAULT 'retail'::text NOT NULL, status text DEFAULT 'active'::text NOT NULL, channel_id uuid, segment text, source text, audience_id uuid, acquired_campaign_id uuid, first_interaction_at timestamp with time zone, first_purchase_at timestamp with time zone, last_activity_at timestamp with time zone, notes text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, lifecycle_stage text DEFAULT 'active'::text NOT NULL, assigned_to uuid, assigned_to_name text, tags text[] DEFAULT '{}'::text[] NOT NULL, last_contacted_at timestamp with time zone, next_follow_up date, converted_at timestamp with time zone, converted_sale_id uuid);
CREATE TABLE public.employees (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, role text, department text, phone text, salary numeric DEFAULT 0 NOT NULL, status text DEFAULT 'Active'::text NOT NULL, hired_on date, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.expense_categories (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid() NOT NULL, name text NOT NULL, parent_name text, active boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.expenses (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), description text NOT NULL, category text, amount numeric DEFAULT 0 NOT NULL, expense_date date DEFAULT CURRENT_DATE NOT NULL, payment_method text, notes text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.finance_accounts (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, account_type text DEFAULT 'Bank'::text NOT NULL, payment_method text DEFAULT 'Bank'::text NOT NULL, account_number text, currency text DEFAULT 'TZS'::text NOT NULL, opening_balance numeric DEFAULT 0 NOT NULL, status text DEFAULT 'Active'::text NOT NULL, notes text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.finance_audit_logs (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), entity text NOT NULL, entity_id uuid, action text NOT NULL, description text, amount numeric DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.finance_payments (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), payment_type text DEFAULT 'Manual Payment'::text NOT NULL, payment_method text DEFAULT 'Cash'::text NOT NULL, account_id uuid, direction text DEFAULT 'out'::text NOT NULL, amount numeric DEFAULT 0 NOT NULL, payment_date date DEFAULT CURRENT_DATE NOT NULL, reference text, customer_id uuid, customer_name text, supplier_id uuid, supplier_name text, invoice_number text, attachment_path text, description text, notes text, status text DEFAULT 'Completed'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.finance_transfers (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), from_account_id uuid, from_account_name text DEFAULT ''::text NOT NULL, to_account_id uuid, to_account_name text DEFAULT ''::text NOT NULL, amount numeric DEFAULT 0 NOT NULL, transfer_date date DEFAULT CURRENT_DATE NOT NULL, reference text, description text, notes text, status text DEFAULT 'Completed'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.income_tax_records (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), period text NOT NULL, installment text, profit_base numeric DEFAULT 0 NOT NULL, tax_rate numeric DEFAULT 30 NOT NULL, amount numeric DEFAULT 0 NOT NULL, due_date date NOT NULL, payment_status text DEFAULT 'Unpaid'::text NOT NULL, status text DEFAULT 'Draft'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.inventory_purchase_items (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), purchase_id uuid NOT NULL, product_id uuid, product_name text NOT NULL, quantity numeric DEFAULT 0 NOT NULL, unit_cost numeric DEFAULT 0 NOT NULL, line_total numeric DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.inventory_purchases (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), purchase_no text NOT NULL, supplier_id uuid, supplier_name text DEFAULT ''::text NOT NULL, warehouse_id uuid, purchase_date date DEFAULT CURRENT_DATE NOT NULL, total numeric DEFAULT 0 NOT NULL, notes text, status text DEFAULT 'Pending'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.market_audiences (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, region text, available_customers integer DEFAULT 0 NOT NULL, reach_customers integer DEFAULT 0 NOT NULL, channels text[] DEFAULT '{}'::text[] NOT NULL, notes text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT market_audiences_available_customers_check CHECK ((available_customers >= 0)), CONSTRAINT market_audiences_reach_customers_check CHECK ((reach_customers >= 0)), CONSTRAINT market_audiences_reach_within_available CHECK ((reach_customers <= available_customers)));
CREATE TABLE public.marketing_activities (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid() NOT NULL, activity_date date DEFAULT CURRENT_DATE NOT NULL, activity_group text DEFAULT 'content'::text NOT NULL, activity_type text NOT NULL, channel text, quantity numeric DEFAULT 1 NOT NULL, cost numeric DEFAULT 0 NOT NULL, owner_name text, campaign_id uuid, expense_id uuid, result text, notes text, attachment_path text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.marketing_campaigns (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, description text, budget numeric DEFAULT 0 NOT NULL, channel text DEFAULT 'sms'::text NOT NULL, status text DEFAULT 'draft'::text NOT NULL, start_date date, end_date date, objective text, template_key text, audience_id uuid, segment text, content text, expected_customers integer DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.marketing_reach (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid() NOT NULL, period text NOT NULL, channel text NOT NULL, channel_id uuid, campaign_id uuid, reached integer DEFAULT 0 NOT NULL, contacted integer DEFAULT 0 NOT NULL, leads integer DEFAULT 0 NOT NULL, converted integer DEFAULT 0 NOT NULL, notes text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.paye_records (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), period text NOT NULL, employees integer DEFAULT 0 NOT NULL, gross_pay numeric DEFAULT 0 NOT NULL, paye_amount numeric DEFAULT 0 NOT NULL, due_date date NOT NULL, payment_status text DEFAULT 'Unpaid'::text NOT NULL, status text DEFAULT 'Draft'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.permission_catalog (permission_key text NOT NULL, module text NOT NULL, action text NOT NULL, description text DEFAULT ''::text NOT NULL, active boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.product_categories (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, description text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.products (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, sku text, barcode text, category text, category_id uuid, supplier_id uuid, warehouse_id uuid, description text, image_path text, selling_price numeric DEFAULT 0 NOT NULL, cost_price numeric DEFAULT 0 NOT NULL, tax_rate numeric DEFAULT 18 NOT NULL, stock_quantity integer DEFAULT 0 NOT NULL, reorder_level integer DEFAULT 5 NOT NULL, active boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.profiles (id uuid NOT NULL, full_name text, business_name text, phone text, status text DEFAULT 'active'::text NOT NULL, last_seen_at timestamp with time zone, business_type text, legal_form text, sector text, activities text[] DEFAULT '{}'::text[] NOT NULL, region text, size_category text, annual_turnover numeric, employee_count integer, does_import boolean DEFAULT false NOT NULL, does_export boolean DEFAULT false NOT NULL, tax_registrations text[] DEFAULT '{}'::text[] NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, logo_path text, business_address text);
CREATE TABLE public.quotation_items (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), quotation_id uuid NOT NULL, product_id uuid, product_name text NOT NULL, quantity numeric DEFAULT 1 NOT NULL, unit_price numeric DEFAULT 0 NOT NULL, tax_amount numeric DEFAULT 0 NOT NULL, line_total numeric DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.quotations (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), quote_no text NOT NULL, customer_id uuid, customer_name text DEFAULT ''::text NOT NULL, quote_date date DEFAULT CURRENT_DATE NOT NULL, valid_until date, subtotal numeric DEFAULT 0 NOT NULL, tax_amount numeric DEFAULT 0 NOT NULL, discount_amount numeric DEFAULT 0 NOT NULL, total numeric DEFAULT 0 NOT NULL, notes text, status text DEFAULT 'Draft'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.role_permissions (id uuid DEFAULT gen_random_uuid() NOT NULL, role public.app_role NOT NULL, permission_key text NOT NULL, scope text DEFAULT 'ALL'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT role_permissions_scope_check CHECK ((scope = ANY (ARRAY['ALL'::text, 'BRANCH'::text, 'DEPARTMENT'::text, 'TEAM'::text, 'OWN'::text]))));
CREATE TABLE public.sale_items (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), sale_id uuid NOT NULL, product_id uuid, product_name text NOT NULL, quantity numeric DEFAULT 1 NOT NULL, unit_price numeric DEFAULT 0 NOT NULL, tax_amount numeric DEFAULT 0 NOT NULL, line_total numeric DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.sales (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), invoice_number text NOT NULL, customer_id uuid, customer_name text, subtotal numeric DEFAULT 0 NOT NULL, tax_amount numeric DEFAULT 0 NOT NULL, discount_amount numeric DEFAULT 0 NOT NULL, total numeric DEFAULT 0 NOT NULL, amount_paid numeric DEFAULT 0 NOT NULL, payment_method text DEFAULT 'cash'::text NOT NULL, status text DEFAULT 'completed'::text NOT NULL, sale_date date DEFAULT CURRENT_DATE NOT NULL, due_date date, notes text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.sales_order_items (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), order_id uuid NOT NULL, product_id uuid, product_name text NOT NULL, quantity numeric DEFAULT 1 NOT NULL, unit_price numeric DEFAULT 0 NOT NULL, tax_amount numeric DEFAULT 0 NOT NULL, line_total numeric DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.sales_orders (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), order_no text NOT NULL, customer_id uuid, customer_name text DEFAULT ''::text NOT NULL, order_date date DEFAULT CURRENT_DATE NOT NULL, delivery_date date, subtotal numeric DEFAULT 0 NOT NULL, tax_amount numeric DEFAULT 0 NOT NULL, discount_amount numeric DEFAULT 0 NOT NULL, total numeric DEFAULT 0 NOT NULL, notes text, status text DEFAULT 'Pending'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.sales_payments (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), sale_id uuid, invoice_number text, customer_name text DEFAULT ''::text NOT NULL, payment_date date DEFAULT CURRENT_DATE NOT NULL, amount numeric DEFAULT 0 NOT NULL, method text DEFAULT 'cash'::text NOT NULL, reference text, notes text, status text DEFAULT 'Received'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.sales_return_items (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), return_id uuid NOT NULL, product_id uuid, product_name text NOT NULL, quantity numeric DEFAULT 1 NOT NULL, unit_price numeric DEFAULT 0 NOT NULL, line_total numeric DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.sales_returns (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), return_no text NOT NULL, sale_id uuid, invoice_number text, customer_name text DEFAULT ''::text NOT NULL, return_date date DEFAULT CURRENT_DATE NOT NULL, reason text, total numeric DEFAULT 0 NOT NULL, status text DEFAULT 'Pending'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.stock_movements (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), product_id uuid, product_name text DEFAULT ''::text NOT NULL, type text NOT NULL, quantity numeric DEFAULT 0 NOT NULL, reference text, notes text, movement_date date DEFAULT CURRENT_DATE NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.stock_transfers (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), product_id uuid, product_name text DEFAULT ''::text NOT NULL, from_warehouse_id uuid, from_warehouse text DEFAULT ''::text NOT NULL, to_warehouse_id uuid, to_warehouse text DEFAULT ''::text NOT NULL, quantity numeric DEFAULT 0 NOT NULL, notes text, transfer_date date DEFAULT CURRENT_DATE NOT NULL, status text DEFAULT 'Pending'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.suppliers (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, phone text, address text, notes text, status text DEFAULT 'Active'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tax_documents (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, category text, type text, size text, status text DEFAULT 'Pending'::text NOT NULL, uploaded_at date DEFAULT CURRENT_DATE NOT NULL, file_path text, file_url text, file_size bigint, sale_id uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tax_expenses (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), description text NOT NULL, category text, date date DEFAULT CURRENT_DATE NOT NULL, amount numeric DEFAULT 0 NOT NULL, deductible boolean DEFAULT true NOT NULL, receipt boolean DEFAULT false NOT NULL, tax_period text NOT NULL, status text DEFAULT 'Pending'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, item text, vat_amount numeric DEFAULT 0 NOT NULL, payee text, supplier_id uuid, payment_method text, reference text, notes text, attachment_path text, branch text, campaign_id uuid, is_recurring boolean DEFAULT false NOT NULL, frequency text DEFAULT 'one_time'::text NOT NULL, next_due_date date, recurring_parent_id uuid);
CREATE TABLE public.tax_imports (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, type text, rows_count integer DEFAULT 0 NOT NULL, duplicates integer DEFAULT 0 NOT NULL, errors integer DEFAULT 0 NOT NULL, status text DEFAULT 'Completed'::text NOT NULL, imported_at date DEFAULT CURRENT_DATE NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tax_purchases (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), supplier text NOT NULL, date date DEFAULT CURRENT_DATE NOT NULL, amount numeric DEFAULT 0 NOT NULL, deductible boolean DEFAULT true NOT NULL, category text, attachment boolean DEFAULT false NOT NULL, tax_period text NOT NULL, status text DEFAULT 'Pending'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tax_sales (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), reference text NOT NULL, customer text NOT NULL, date date DEFAULT CURRENT_DATE NOT NULL, amount numeric DEFAULT 0 NOT NULL, vat numeric DEFAULT 0 NOT NULL, tax_period text NOT NULL, status text DEFAULT 'Pending'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.tax_settings (user_id uuid DEFAULT auth.uid() NOT NULL, tax_rate numeric DEFAULT 30 NOT NULL, projected_annual_profit numeric DEFAULT 0 NOT NULL, reminders_off text[] DEFAULT '{}'::text[] NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.user_permission_overrides (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, permission_key text NOT NULL, effect text NOT NULL, scope text DEFAULT 'ALL'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT user_permission_overrides_effect_check CHECK ((effect = ANY (ARRAY['allow'::text, 'deny'::text]))), CONSTRAINT user_permission_overrides_scope_check CHECK ((scope = ANY (ARRAY['ALL'::text, 'BRANCH'::text, 'DEPARTMENT'::text, 'TEAM'::text, 'OWN'::text]))));
CREATE TABLE public.user_roles (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, role public.app_role NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.vat_returns (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), period text NOT NULL, output_vat numeric DEFAULT 0 NOT NULL, input_vat numeric DEFAULT 0 NOT NULL, payable numeric DEFAULT 0 NOT NULL, due_date date NOT NULL, payment_status text DEFAULT 'Unpaid'::text NOT NULL, status text DEFAULT 'Draft'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.warehouses (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, location text, manager text, capacity integer DEFAULT 0 NOT NULL, status text DEFAULT 'Active'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.withholding_records (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid DEFAULT auth.uid(), name text NOT NULL, certificate text, type text, date date DEFAULT CURRENT_DATE NOT NULL, period text NOT NULL, due_date date NOT NULL, amount numeric DEFAULT 0 NOT NULL, payment_status text DEFAULT 'Unpaid'::text NOT NULL, status text DEFAULT 'Pending'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);